\begin{itemchoice}
			\itemch Tổng số hình: $3 + 4 = 7$ hình (Đúng).\
			\itemch Số hình tròn (3) ít hơn số hình tam giác (4) nên phát biểu nhiều hơn là Sai.\
			\itemch Số hình tam giác nhiều hơn số hình tròn: $4 - 3 = 1$ hình (Đúng).\
			\itemch Có 4 hình tam giác, bớt 2 hình thì còn $4 - 2 = 2$ hình, phát biểu còn 5 hình là Sai.\
		\end{itemchoice}

\begin{itemchoice}
			\itemch $32 + 45 = 77$ (Đúng).\
			\itemch $99 - 9 = 90$ đơn vị (tức là $9$ chục), phát biểu viết là $90$ chục (tức là 900) là Sai.\
			\itemch $50 + 20 = 70$; $80 - 20 = 60$. Vì $70 > 60$ nên phát biểu nhỏ hơn là Sai.\
			\itemch $45 - 40 = 5$, nên số điền vào ô trống là số 5 (Đúng).\
		\end{itemchoice}

\begin{itemchoice}
			\itemch Lan có 12, Mai có 15. $12 < 15$ nên Lan ít gà hơn Mai (Sai).\
			\itemch Tổng số gà: $12 + 15 = 27$ con (Đúng).\
			\itemch Nhà Mai nhiều hơn nhà Lan: $15 - 12 = 3$ con (Đúng).\
			\itemch Mai bán đi 5 con thì còn $15 - 5 = 10$ con. Lan có 12 con. $10 \neq 12$ nên không bằng nhau (Sai).\
		\end{itemchoice}

\begin{itemchoice}
			\itemch Các số có hai chữ số chạy từ 10 đến 99, vậy số 10 nhỏ nhất (Đúng).\
			\itemch Số lớn nhất có một chữ số là số 9. Số 10 là số có hai chữ số (Sai).\
			\itemch Cái hộp diêm có hình dạng là khối hộp chữ nhật, không phải khối lập phương (Sai).\
			\itemch Số 85 đọc chuẩn là tám mươi lăm (Đúng).\
		\end{itemchoice}
